{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history shows low positivity (0.00) and true outcomes consistently dip below forecasts.",
    "Increase forecast sensitivity to recent high prices (last 3-5 days) when sentiment includes positive signals (e.g., 0.33 or 0.50) to avoid underestimating upward momentum.",
    "Apply mean reversion correction: if forecast is > 10% above recent 5-day average, reduce by 5-10% unless sentiment strongly bullish.",
    "Reduce forecast overshoot after sharp spikes (e.g., >15% above prior peak) by 10-20% to prevent overcorrection.",
    "When sentiment is neutral (0.00) and true outcome is trending downward, shift forecast toward lower end of recent 15-day range to avoid lagged overreaction.",
    "For long-term (30-day) forecasts, apply smoothing: if true outcome deviates >15% from forecast, adjust next period’s forecast toward observed trend, not model’s extrapolation."
  ]
}
